import java.util.*;

class Solution {
    public List<Object> shuffleAllDecks(List<Object> allDecks) {
        List<Object> arr = new ArrayList<>(allDecks);
        Random rnd = new Random();
        for (int i = arr.size() - 1; i > 0; i--) {
            int j = rnd.nextInt(i + 1);
            Collections.swap(arr, i, j);
        }
        return arr;
    }
}

#include <bits/stdc++.h>
using namespace std;

struct Card { string suit, rank; };

class Solution {
public:
    list<Card> shuffleAllDecks(const list<Card>& all_decks) {
        static mt19937 rng(random_device{}());
        vector<Card> arr(all_decks.begin(), all_decks.end());
        for (int i = (int)arr.size() - 1; i > 0; --i) {
            uniform_int_distribution<int> pick(0, i);
            swap(arr[i], arr[pick(rng)]);
        }
        return list<Card>(arr.begin(), arr.end());
    }
};
